"""Constant tensor blocks reuse only numerically identical solver results."""

from collections.abc import Mapping, Sequence
from dataclasses import replace
from unittest.mock import patch

import pytest
import torch

from flagquantum.compiler.optimization import two_qubit_optimization as two
from flagquantum.core.ir import CircuitIR, Instruction
from flagquantum.core.parameters import Parameter
from flagquantum.simulation.statevector.local import run_local_statevector

pytestmark = pytest.mark.unit


@pytest.mark.parametrize(
    "dtype, angles",
    [(torch.float64, (0.25, 0.5)), (torch.float32, (0.25, 0.5)), (torch.int64, (1, 1))],
)
def test_constant_tensor_blocks_reuse_across_pairs_without_losing_metadata(
    dtype: torch.dtype, angles: tuple[float, float]
) -> None:
    source = CircuitIR(
        4,
        tuple(
            item
            for index, pair in enumerate(((0, 1), (2, 3), (1, 0), (3, 2)))
            for item in (
                Instruction(
                    "rzz",
                    pair,
                    {"theta": torch.tensor(angles[0], dtype=dtype)},
                    metadata={"block": index},
                ),
                Instruction(
                    "rzz", pair, {"theta": torch.tensor(angles[1], dtype=dtype)}
                ),
                Instruction("ccx", (0, 1, 2)),
            )
        ),
        dtype="complex128",
    )
    with patch.object(two, "_replacement", wraps=two._replacement) as solver:
        folded = two.collapse_two_qubit_blocks(source)
    assert solver.call_count == 1
    assert [(item.wires, item.metadata) for item in folded.instructions[::2]] == [
        (pair, {"block": index})
        for index, pair in enumerate(((0, 1), (2, 3), (1, 0), (3, 2)))
    ]
    # Compare every basis input, including phase, through the independent runtime.
    for basis in range(16):
        preparation = tuple(
            Instruction("x", (wire,)) for wire in range(4) if basis & (1 << wire)
        )
        before, after = (
            run_local_statevector(
                replace(ir, instructions=preparation + ir.instructions),
                batch_size=1,
                device=torch.device("cpu"),
                dtype=torch.complex128,
            )
            for ir in (source, folded)
        )
        torch.testing.assert_close(after, before, rtol=0, atol=1e-12)


def test_mutated_scalar_is_read_again_between_blocks_and_invocations() -> None:
    angle = torch.tensor(0.25, dtype=torch.float64)
    source = CircuitIR(
        3,
        tuple(
            item
            for pair in ((0, 1), (1, 2))
            for item in (
                Instruction("rzz", pair, {"theta": angle}),
                Instruction("rzz", pair, {"theta": 0.5}),
                Instruction("ccx", (0, 1, 2)),
            )
        ),
    )
    original = two._replacement

    def solve_then_mutate(
        instructions: Sequence[Instruction],
        *,
        pair: tuple[int, ...],
        metadata: Mapping[str, object],
    ) -> tuple[Instruction, ...] | None:
        result = original(instructions, pair=pair, metadata=metadata)
        angle.fill_(0.75)
        return result

    with patch.object(two, "_replacement", side_effect=solve_then_mutate) as solver:
        folded = two.collapse_two_qubit_blocks(source)
    assert solver.call_count == 2
    assert [item.params["theta"] for item in folded.instructions[::2]] == pytest.approx(
        [0.75, 1.25]
    )
    angle.fill_(1.0)
    later = two.collapse_two_qubit_blocks(source)
    assert [item.params["theta"] for item in later.instructions[::2]] == pytest.approx(
        [1.5, 1.5]
    )


@pytest.mark.parametrize(
    "value",
    [
        torch.tensor(0.5, requires_grad=True),
        torch.nn.Parameter(torch.tensor(0.5), requires_grad=False),
        torch.tensor([0.5]),
        Parameter("theta"),
        Parameter("theta") + 0.5,
    ],
)
def test_nonconstant_or_unsupported_values_bypass_reuse(value: object) -> None:
    assert (
        two._block_key([Instruction("rzz", (0, 1), {"theta": value})], (0, 1)) is None
    )


@pytest.mark.parametrize("value", [float("nan"), float("inf"), -float("inf")])
def test_scalar_mutated_to_nonfinite_value_bypasses_reuse(value: float) -> None:
    angle = torch.tensor(0.5, dtype=torch.float64)
    instruction = Instruction("rzz", (0, 1), {"theta": angle})
    angle.fill_(value)
    assert two._block_key([instruction], (0, 1)) is None


def test_shared_trainable_angle_and_its_gradient_survive_the_pass() -> None:
    angle = torch.tensor(0.25, dtype=torch.float64, requires_grad=True)
    source = CircuitIR(
        2, tuple(Instruction("rzz", (0, 1), {"theta": angle}) for _ in range(2))
    )
    folded = two.collapse_two_qubit_blocks(source)
    assert all(item.params["theta"] is angle for item in folded.instructions)
    state = run_local_statevector(
        folded, batch_size=1, device=torch.device("cpu"), dtype=torch.complex128
    )
    state.real.sum().backward()
    torch.testing.assert_close(angle.grad, -angle.detach().sin(), rtol=0, atol=1e-12)


def test_exact_values_preserve_signed_zero_and_operand_roles() -> None:
    def key(value: float, wire: int = 0) -> two._BlockKey | None:
        return two._block_key(
            [
                Instruction(
                    "rz", (wire,), {"theta": torch.tensor(value, dtype=torch.float64)}
                )
            ],
            (0, 1),
        )

    assert key(0.0) != key(-0.0)
    assert key(0.5) != key(0.5000000000000001)
    assert key(0.5, 0) != key(0.5, 1)
